def drive(me, enemy, arena):
    try:
        if not me.can_drive:
            return (0, 0)
        if me.on_side or me.righting:
            return (0, 0)

        ex = enemy.x - me.x
        ey = enemy.y - me.y
        dist_e = hypot(ex, ey)
        ang_e = bearing_to(enemy.x, enemy.y)
        center_dist = hypot(me.x, me.y)

        if center_dist > 5.0:
            ang = bearing_to(0, 0)
        else:
            fl_ready = False
            wback = me.weapons.get("back")
            if wback is not None and wback.get("type") == "flipper":
                if wback.get("health", 0) > 0 and wback.get("ready") and wback.get("shots_left", 0) > 1:
                    fl_ready = True

            if fl_ready and dist_e < 1.1 and abs(ang_e) > 135:
                return (-0.8, -0.8)

            ang = ang_e

        if ang > 12:
            return (0.0, 0.8)
        if ang < -12:
            return (0.8, 0.0)
        return (0.8, 0.8)
    except:
        return (0, 0)


def weapons(me, enemy, arena):
    try:
        if me.battery_health <= 0 or me.righting or me.on_side or me.airborne:
            return None

        wback = me.weapons.get("back")
        fl = None
        if wback is not None and wback.get("type") == "flipper" and wback.get("health", 0) > 0:
            fl = wback

        dist_e = hypot(enemy.x - me.x, enemy.y - me.y)
        center_dist = hypot(me.x, me.y)

        if me.inverted and fl is not None and fl.get("ready") and fl.get("shots_left", 0) > 0:
            if dist_e > 1.2 and center_dist < 5.0:
                return [self_right()]

        cmds = []

        wfront = me.weapons.get("front")
        if wfront is not None and wfront.get("type") == "spinner" and wfront.get("health", 0) > 0:
            cmds.append(spin("front", 3500))

        if fl is not None and not me.inverted:
            if fl.get("ready") and fl.get("shots_left", 0) > 1 and dist_e < 1.1:
                ang_e = bearing_to(enemy.x, enemy.y)
                if abs(ang_e) > 135:
                    if not enemy.airborne and not enemy.righting and not enemy.on_side:
                        cmds.append(flip("back"))

        if cmds:
            return cmds
        return None
    except:
        return None

