def drive(me, enemy, arena):
    try:
        if not me.can_drive or me.righting or me.on_side:
            return (0, 0)

        ex = enemy.x - me.x
        ey = enemy.y - me.y
        d = hypot(ex, ey)
        r = hypot(me.x, me.y)

        if r > 5.4 and d > 2.0:
            ang = bearing_to(0, 0)
        else:
            ang = bearing_to(enemy.x, enemy.y)

        if d < 0.55:
            if ey >= 0:
                ang += 35
            else:
                ang -= 35
            if ang > 180:
                ang -= 360
            elif ang < -180:
                ang += 360

        if d < 1.1 and abs(ang) > 120 and not me.inverted:
            wb = me.weapons.get("back")
            if wb and wb.get("type") == "flipper" and wb.get("ready") and wb.get("shots_left", 0) > 1:
                return (-0.8, -0.8)

        if ang > 12:
            return (0.0, 0.8)
        if ang < -12:
            return (0.8, 0.0)
        return (0.8, 0.8)
    except:
        return (0, 0)


def weapons(me, enemy, arena):
    try:
        wf = me.weapons.get("front")
        wb = me.weapons.get("back")
        fl_ready = False
        shots = 0

        if wb and wb.get("type") == "flipper" and wb.get("health", 0) > 0:
            shots = wb.get("shots_left", 0)
            fl_ready = wb.get("ready")

        if me.battery_health <= 0:
            return None

        if me.on_side:
            if fl_ready and shots > 0:
                return [self_right()]
            return None

        if me.airborne or me.righting:
            return None

        ex = enemy.x - me.x
        ey = enemy.y - me.y
        d = hypot(ex, ey)
        ang = bearing_to(enemy.x, enemy.y)

        if me.inverted and fl_ready and shots > 1 and d > 1.4:
            return [self_right()]

        cmds = []

        if wf and wf.get("type") == "spinner" and wf.get("health", 0) > 0:
            temp = wf.get("temperature", 25)
            rpm = 2800
            if temp < 60:
                rpm = 3200
            elif temp > 105:
                rpm = 1800
            elif temp > 130:
                rpm = 800
            elif temp > 150:
                rpm = 0

            if wf.get("health", 1) < 0.3 and rpm > 1600:
                rpm = 1600
            if me.battery_health < 0.2 and rpm > 1200:
                rpm = 1200

            cmds.append(spin("front", rpm))

        if not me.inverted and fl_ready:
            if (shots > 1 or enemy.health < 0.25) and d < 1.0 and abs(ang) > 120:
                if not enemy.airborne and not enemy.on_side and not enemy.righting:
                    cmds.append(flip("back"))

        return cmds if cmds else None
    except:
        return None

